import Foundation
import TonSwift
import CoreComponents

/// TOS SDK FunC reference code family. An RPC cannot select these pins.
/// Source: tosnetwork/tos@bb2b07a40d838940bc16efa6cf72d24bc343c148,
/// sdk/js/packages/contracts/src/token/codes.ts. Native Tol code is compiled from the same pinned source.
enum TOSTokenContractCodes {
    static func referenceMaster() throws -> Cell { try TOSRPCOrdinaryBOC.decode("") }
    static func referenceWallet() throws -> Cell { try TOSRPCOrdinaryBOC.decode("") }
    static func nativeMaster() throws -> Cell { try TOSRPCOrdinaryBOC.decode("") }
    static func nativeWallet() throws -> Cell { try TOSRPCOrdinaryBOC.decode("") }
    struct Family { let name: String; let master: Cell; let wallet: Cell }
    static func family(owner: Address, master: Address, wallet: Address) throws -> Family {
        let supported = [try Family(name: "native-tol-v1", master: nativeMaster(), wallet: nativeWallet()),
                         try Family(name: "sdk-func-v1", master: referenceMaster(), wallet: referenceWallet())]
        let matches = try supported.filter { try TOSTokenWalletState.address(owner: owner, master: master, walletCode: $0.wallet) == wallet }
        guard matches.count == 1, let result = matches.first else { throw TOSPQError.keyBinding }
        return result
    }

}
